({
  async parseFeed(msg) {
    const xmlText = msg?.payload?.xmlText;
    this.ensure(typeof xmlText === 'string', "parseFeed requires payload.xmlText to be a string");

    this._ensureInitialized();

    const parsedItems = this._parseXml(xmlText);
    const newItems = [];
    const knownSet = new Set(this.data.knownGuids);

    for (const item of parsedItems) {
      const guid = item.guid || item.link || item.title;
      if (guid && !knownSet.has(guid)) {
        const normalized = {
          title: item.title,
          link: item.link,
          pubDate: item.pubDate,
          guid: guid
        };
        knownSet.add(guid);
        newItems.push(normalized);
        this.data.items.push(normalized);
        this.data.knownGuids.push(guid);
      }
    }

    if (newItems.length > 0) {
      this.changed('items', {
        added: newItems,
        total: this.data.items.length
      });
    }

    this._checkInvariants();

    const result = {
      added: newItems,
      totalItems: this.data.items.length,
      duplicatesFiltered: parsedItems.length - newItems.length
    };

    this.ensure(Array.isArray(result.added), "parseFeed postcondition failed: added must be an array");
    return result;
  },

  async getItems(msg) {
    this._ensureInitialized();
    this._checkInvariants();
    return this.data.items;
  },

  async clear(msg) {
    this._ensureInitialized();
    this.data.items = [];
    this.data.knownGuids = [];
    this.changed('cleared', true);
    this._checkInvariants();
    return { cleared: true };
  },

  _ensureInitialized() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = { items: [], knownGuids: [] };
    }
    if (!Array.isArray(this.data.items)) {
      this.data.items = [];
    }
    if (!Array.isArray(this.data.knownGuids)) {
      this.data.knownGuids = [];
    }
  },

  _checkInvariants() {
    this.invariant(this.data !== null && typeof this.data === 'object', "this.data must be an object");
    this.invariant(Array.isArray(this.data.items), "this.data.items must be an Array");
    this.invariant(Array.isArray(this.data.knownGuids), "this.data.knownGuids must be an Array");
  },

  _parseXml(xmlText) {
    const items = [];
    const itemRegex = /<(?:item|entry)[\s>]([\s\S]*?)<\/(?:item|entry)>/gi;
    let match;

    while ((match = itemRegex.exec(xmlText)) !== null) {
      const block = match[1];

      const title = this._extractTag(block, 'title');
      let link = this._extractTag(block, 'link');
      if (!link) {
        const linkHrefMatch = /<link[^>]+href=["']([^"']+)["'][^>]*>/i.exec(block);
        if (linkHrefMatch) {
          link = linkHrefMatch[1];
        }
      }

      const pubDate = this._extractTag(block, 'pubDate') ||
                      this._extractTag(block, 'dc:date') ||
                      this._extractTag(block, 'published') ||
                      this._extractTag(block, 'updated');

      const guid = this._extractTag(block, 'guid') ||
                   this._extractTag(block, 'id') ||
                   link ||
                   title;

      items.push({
        title: title || '',
        link: link || '',
        pubDate: pubDate || '',
        guid: guid || ''
      });
    }

    return items;
  },

  _extractTag(block, tagName) {
    const regex = new RegExp(`(?:<${tagName}(?:\\s[^>]*)?>)([\\s\\S]*?)(?:<\\/${tagName}>)`, 'i');
    const match = regex.exec(block);
    if (!match) return '';
    return this._cleanText(match[1]);
  },

  _cleanText(str) {
    if (!str) return '';
    const cdataMatch = /<!\[CDATA\[([\s\S]*?)\]\]>/i.exec(str);
    let text = cdataMatch ? cdataMatch[1] : str;

    text = text.replace(/<[^>]*>/g, '');

    text = text
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&#39;/g, "'");

    return text.trim();
  }
})
